mapper.select:
with ranked as ( select c.id, s.name as source_name, c.source_type, c.source_official_level, c.content_type, coalesce(c.title_zh, c.original_title) as title, c.original_title, c.summary_zh as summary, c.recommendation_reason, c.original_url, c.canonical_url, c.fact_status, c.final_score, c.featured, c.source_published_at, c.effective_published_at as published_at, row_number() over(partition by c.source_entity_id order by c.effective_published_at desc,c.id desc) source_rank from content.content_item c join source.source_entity s on s.id = c.source_entity_id where and c.featured = true
and (c.effective_published_at, c.id) < (#{cursorPublishedAt}, #{cursorId})
) select id,source_name,source_type,source_official_level,content_type,title,original_title,summary, recommendation_reason,original_url,canonical_url,fact_status,final_score,featured, source_published_at,published_at from ranked where source_rank <= case when source_official_level in ('OFFICIAL','FIRST_PARTY') then 4 else 2 end8 order by published_at desc,id desc limit #{limit}
